function validate(input) {
  const [nums, starts] = input;
  if (nums.length !== 3 || [...nums].sort((a, b) => a - b).join() !== '1,2,3') return 'nums must be a permutation of [1, 2, 3].';
  if (starts.length !== 3) return 'starts needs 3 start times, one per thread.';
  if (!starts.every((t) => t >= 0 && t <= 1000)) return 'Each start time is from 0 to 1000 ms.';
  return null;
}

