function adapt(input, solve, kit) {
  const [nums, starts] = input, start = Date.now(), prints = [];
  const names = ['first', 'second', 'third'], threads = ['A', 'B', 'C'];
  const foo = new solve();
  for (const name of names) if (!foo || typeof foo[name] !== 'function') throw new Error(`Foo needs a method ${name}.`);
  nums.forEach((number, i) => {
    const name = names[number - 1];
    const print = () => {
      prints.push({ text: name, t: Date.now() - start });
      kit.trace(`"${name}" is printed`);
    };
    setTimeout(() => {
      kit.trace(`Thread ${threads[i]} starts and calls ${name}()`);
      foo[name](print);
    }, starts[i]);
  });
  // A correct solution has printed everything by the last start; the extra time shows late prints.
  return new Promise((resolve) => setTimeout(() => resolve({
    output: prints.map((p) => p.text).join(''),
    times: prints.map((p) => p.t),
  }), Math.max(...starts) + 50));
}

