class Foo {
  constructor() {
    this.turn = 1;
    this.parked = [];
  }

  // Park the print under its turn number, then run every print whose turn has come.
  take(order, print) {
    this.parked[order] = print;
    while (this.parked[this.turn]) {
      const next = this.parked[this.turn];
      this.parked[this.turn] = null;
      this.turn += 1;
      next();
    }
  }

  first(printFirst) { this.take(1, printFirst); }
  second(printSecond) { this.take(2, printSecond); }
  third(printThird) { this.take(3, printThird); }
}

