function generate(rand, size) {
  const nums = [1, 2, 3];
  for (let i = 2; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [nums[i], nums[j]] = [nums[j], nums[i]];
  }
  const top = size === 'small' ? 30 : 1000, roll = rand();
  const same = Math.floor(rand() * (top + 1));
  const starts = nums.map(() => (roll < 0.15 ? 0 : roll < 0.3 ? same : Math.floor(rand() * (top + 1))));
  return [nums, starts];
}
